    expect(budgetProblem(BUDGET_BYTES + 1)).toMatch(/over the 150 MB budget/);
    expect(budgetProblem(BUDGET_BYTES)).toBeUndefined();
    expect(budgetProblem(3000 * 25 * 1024)).toBeUndefined();
  });
});
